using NexaStation.Core;
using NexaStation.Domain;
using NexaStation.Media.Associations;
using NexaStation.Media.Hub;
using NexaStation.Media.Recent;
using Xunit;

namespace NexaStation.Media.Tests;

public sealed class MediaTests
{
    [Theory][InlineData(MediaAssociationScope.GlobalMediaType,1)][InlineData(MediaAssociationScope.FileExtension,2)][InlineData(MediaAssociationScope.GallerySource,3)][InlineData(MediaAssociationScope.MediaItem,4)]public async Task ResolvesEveryAssociationScope(MediaAssociationScope scope,int expectedSpecificity){string id=expectedSpecificity.ToString(System.Globalization.CultureInfo.InvariantCulture);MemoryPersistence p=new();GalleryMediaItem item=Item();p.Associations.Add(Association(scope,item,id));MediaAssociation? result=await new MediaAssociationService(p,new Library()).ResolveAsync(item);Assert.Equal(id,result?.Id);}
    [Fact]public async Task ItemAssociationOverridesAllOthers(){MemoryPersistence p=new();GalleryMediaItem item=Item();foreach(MediaAssociationScope scope in Enum.GetValues<MediaAssociationScope>())p.Associations.Add(Association(scope,item,scope.ToString()));MediaAssociation result=(await new MediaAssociationService(p,new Library()).ResolveAsync(item))!;Assert.Equal(MediaAssociationScope.MediaItem,result.ScopeType);}
    [Fact]public async Task SourceAssociationOverridesExtension(){MemoryPersistence p=new();GalleryMediaItem item=Item();p.Associations.Add(Association(MediaAssociationScope.FileExtension,item,"extension"));p.Associations.Add(Association(MediaAssociationScope.GallerySource,item,"source"));Assert.Equal("source",(await new MediaAssociationService(p,new Library()).ResolveAsync(item))?.Id);}
    [Theory][InlineData("{MEDIA_PATH} && calc")][InlineData("{MEDIA_PATH} | more")][InlineData("{MEDIA_PATH} > out")][InlineData("{MEDIA_PATH} < in")][InlineData("{OTHER}")][InlineData("{{MEDIA_PATH}")][InlineData("{MEDIA_PATH}}")]
    public void UnsafeTemplatesAreRejected(string template)=>Assert.False(MediaAssociationService.IsSafeTemplate(template));
    [Theory][InlineData(null)][InlineData("")][InlineData("{MEDIA_PATH}")][InlineData("--open \"{MEDIA_PATH}\"")]public void SafeTemplatesAreAccepted(string? template)=>Assert.True(MediaAssociationService.IsSafeTemplate(template));
    [Fact]public async Task UnicodeAndSpacesArePreservedInPreview(){MemoryPersistence p=new();GalleryMediaItem item=Item() with{FilePath=@"C:\وسائط محلية\فيلم رائع.mp4"};Library library=new();library.Items.Add(Player());p.Associations.Add(Association(MediaAssociationScope.MediaItem,item,"item") with{PlayerLibraryItemId="player",LaunchTargetId="target",ArgumentsTemplate="{MEDIA_PATH}"});MediaLaunchPlan plan=await new MediaAssociationService(p,library).CreateLaunchPlanAsync(item);Assert.Contains(item.FilePath,plan.Preview,StringComparison.Ordinal);}
    [Fact]public async Task MissingPreferredPlayerDoesNotSilentlyFallback(){MemoryPersistence p=new();GalleryMediaItem item=Item();p.Associations.Add(Association(MediaAssociationScope.MediaItem,item,"item") with{PlayerLibraryItemId="missing"});MediaLaunchPlan plan=await new MediaAssociationService(p,new Library()).CreateLaunchPlanAsync(item);Assert.False(plan.UseWindowsDefault);Assert.NotNull(plan.FailureReason);}
    [Fact]public async Task NoAssociationSelectsWindowsDefault(){MediaLaunchPlan plan=await new MediaAssociationService(new MemoryPersistence(),new Library()).CreateLaunchPlanAsync(Item());Assert.True(plan.UseWindowsDefault);}
    [Fact]public async Task SuccessfulOpenCanBeRecorded(){MemoryPersistence p=new();RecentMediaService service=new(p,new Gallery(Item()));await service.RecordOpenedAsync(Recent(Item().Id));Assert.Single(p.Recent);}
    [Fact]public async Task PrivateGalleryMediaIsExcluded(){GalleryMediaItem item=Item() with{SourcePrivacyLevel=GalleryPrivacyLevel.Private};MemoryPersistence p=new();await new RecentMediaService(p,new Gallery(item)).RecordOpenedAsync(Recent(item.Id));Assert.Empty(p.Recent);}
    [Fact]public async Task MissingMediaRemainsInHistory(){MemoryPersistence p=new();p.Recent.Add(Recent("missing"));Assert.Single(await p.GetRecentAsync(10));}
    [Theory][InlineData(ContentType.Media,null,true)][InlineData(ContentType.Application,"Media",true)][InlineData(ContentType.Application,"Streaming",true)][InlineData(ContentType.Application,"Entertainment",true)][InlineData(ContentType.Application,"Music",true)][InlineData(ContentType.Application,"Video",true)][InlineData(ContentType.Application,"Games",false)]public void MediaClassificationUsesPhaseFourCategories(ContentType type,string? category,bool expected)=>Assert.Equal(expected,MediaHubService.IsMediaApplication(Player() with{ContentType=type,PrimaryCategoryName=category}));
    [Theory][InlineData("Realtek Audio Console","Media",false)][InlineData("Sound Settings","Media",false)][InlineData("Vendor Audio Control","Entertainment",false)][InlineData("Spotify","Streaming",true)]public void AudioUtilitiesAreNotAutomaticallyMediaServices(string title,string category,bool expected)=>Assert.Equal(expected,MediaHubService.IsMediaApplication(Player() with{Title=title,SortTitle=title,PrimaryCategoryName=category}));

    private static GalleryMediaItem Item()=>new(){Id="media",GallerySourceId="source",MediaType=GalleryMediaType.Video,FilePath=@"C:\Media\movie.mp4",NormalizedFilePath=@"c:\media\movie.mp4",FileName="movie.mp4",Extension=".mp4",ParentFolder=@"C:\Media",ModifiedAtUtc=DateTime.UtcNow,AddedAtUtc=DateTime.UtcNow,UpdatedAtUtc=DateTime.UtcNow,SourcePrivacyLevel=GalleryPrivacyLevel.Normal};
    private static RecentMediaEntry Recent(string id)=>new(Guid.NewGuid().ToString("N"),id,GalleryMediaType.Video,DateTime.UtcNow,MediaLaunchMethod.WindowsDefault,null,MediaTrackingConfidence.Requested);
    private static MediaAssociation Association(MediaAssociationScope scope,GalleryMediaItem item,string id)=>new(id,scope,scope switch{MediaAssociationScope.MediaItem=>item.Id,MediaAssociationScope.GallerySource=>item.GallerySourceId,MediaAssociationScope.FileExtension=>item.Extension,_=>null},scope==MediaAssociationScope.GlobalMediaType?item.MediaType:null,scope==MediaAssociationScope.FileExtension?item.Extension:null,null,null,"{MEDIA_PATH}",ApplicationTrackingMode.None,false,false,DateTime.UtcNow,DateTime.UtcNow);
    private static LibraryItem Player(){LaunchTarget target=new(LaunchType.Executable,Environment.ProcessPath!){Id="target",LibraryItemId="player"};return new(){Id="player",Title="Player",SortTitle="Player",ContentType=ContentType.Application,AddedAtUtc=DateTime.UtcNow,UpdatedAtUtc=DateTime.UtcNow,DefaultLaunchTargetId=target.Id,LaunchTargets=[target]};}
    private sealed class MemoryPersistence:IMediaPersistence{public List<MediaAssociation> Associations{get;}=[];public List<RecentMediaEntry> Recent{get;}=[];public Task SaveAssociationAsync(MediaAssociation value,CancellationToken cancellationToken=default){Associations.RemoveAll(x=>x.Id==value.Id);Associations.Add(value);return Task.CompletedTask;}public Task<IReadOnlyList<MediaAssociation>> GetAssociationsAsync(CancellationToken cancellationToken=default)=>Task.FromResult<IReadOnlyList<MediaAssociation>>(Associations);public Task AddRecentAsync(RecentMediaEntry value,CancellationToken cancellationToken=default){Recent.Add(value);return Task.CompletedTask;}public Task<IReadOnlyList<RecentMediaEntry>> GetRecentAsync(int maximumResults,CancellationToken cancellationToken=default)=>Task.FromResult<IReadOnlyList<RecentMediaEntry>>(Recent.Take(maximumResults).ToArray());}
    private sealed class Library:ILibraryRepository{public List<LibraryItem> Items{get;}=[];public Task<IReadOnlyList<LibraryItem>> QueryAsync(LibraryQuery query,CancellationToken cancellationToken=default)=>Task.FromResult<IReadOnlyList<LibraryItem>>(Items);public Task<LibraryItem?> GetByIdAsync(string id,CancellationToken cancellationToken=default)=>Task.FromResult(Items.FirstOrDefault(x=>x.Id==id));public Task AddAsync(LibraryItem item,CancellationToken cancellationToken=default){Items.Add(item);return Task.CompletedTask;}public Task UpdateAsync(LibraryItem item,CancellationToken cancellationToken=default)=>Task.CompletedTask;public Task DeleteAsync(string id,CancellationToken cancellationToken=default)=>Task.CompletedTask;public Task SetFavoriteAsync(string id,bool favorite,CancellationToken cancellationToken=default)=>Task.CompletedTask;public Task SetHiddenAsync(string id,bool hidden,CancellationToken cancellationToken=default)=>Task.CompletedTask;public Task<LibraryItem?> FindDuplicateAsync(LaunchTarget target,CancellationToken cancellationToken=default)=>Task.FromResult<LibraryItem?>(null);}
    private sealed class Gallery(GalleryMediaItem item):GalleryStub{public override Task<GalleryMediaItem?> GetMediaItemAsync(string id,CancellationToken cancellationToken=default)=>Task.FromResult<GalleryMediaItem?>(id==item.Id?item:null);}
}

public abstract class GalleryStub:IGalleryPersistence
{
    public virtual Task<GalleryMediaItem?> GetMediaItemAsync(string id,CancellationToken c=default)=>Task.FromResult<GalleryMediaItem?>(null);public Task<IReadOnlyList<GallerySource>> GetSourcesAsync(CancellationToken c=default)=>Task.FromResult<IReadOnlyList<GallerySource>>([]);public Task<GallerySource?> GetSourceAsync(string id,CancellationToken c=default)=>Task.FromResult<GallerySource?>(null);public Task<IReadOnlyList<GallerySourceOverlap>> FindSourceOverlapsAsync(string p,CancellationToken c=default)=>Task.FromResult<IReadOnlyList<GallerySourceOverlap>>([]);public Task AddSourceAsync(GallerySource s,CancellationToken c=default)=>Task.CompletedTask;public Task UpdateSourceAsync(GallerySource s,CancellationToken c=default)=>Task.CompletedTask;public Task RemoveSourceAsync(string id,CancellationToken c=default)=>Task.CompletedTask;public Task<GalleryRefreshResult> ApplyScanAsync(GallerySourceScanResult s,IReadOnlyList<GalleryMediaInspectionResult> i,CancellationToken c=default)=>throw new NotSupportedException();public Task<IReadOnlyList<GalleryMediaItem>> QueryAsync(GalleryQuery q,CancellationToken c=default)=>Task.FromResult<IReadOnlyList<GalleryMediaItem>>([]);public Task SetFavoriteAsync(string id,bool v,CancellationToken c=default)=>Task.CompletedTask;public Task SetHiddenAsync(string id,bool v,CancellationToken c=default)=>Task.CompletedTask;public Task MarkOpenedAsync(string id,DateTime at,CancellationToken c=default)=>Task.CompletedTask;public Task RelinkMediaAsync(string id,string p,string n,long s,DateTime m,CancellationToken c=default)=>Task.CompletedTask;public Task RemoveMediaIndexAsync(string id,CancellationToken c=default)=>Task.CompletedTask;public Task<GalleryThumbnail?> GetThumbnailAsync(string id,GalleryThumbnailType t,CancellationToken c=default)=>Task.FromResult<GalleryThumbnail?>(null);public Task UpsertThumbnailAsync(GalleryThumbnail t,CancellationToken c=default)=>Task.CompletedTask;public Task RemoveThumbnailsAsync(string id,CancellationToken c=default)=>Task.CompletedTask;public Task<IReadOnlyList<GalleryThumbnail>> GetThumbnailLruAsync(CancellationToken c=default)=>Task.FromResult<IReadOnlyList<GalleryThumbnail>>([]);public Task<IReadOnlyList<GalleryAlbum>> GetAlbumsAsync(CancellationToken c=default)=>Task.FromResult<IReadOnlyList<GalleryAlbum>>([]);public Task<GalleryAlbum?> GetAlbumAsync(string id,CancellationToken c=default)=>Task.FromResult<GalleryAlbum?>(null);public Task SaveAlbumAsync(GalleryAlbum a,CancellationToken c=default)=>Task.CompletedTask;public Task DeleteAlbumAsync(string id,CancellationToken c=default)=>Task.CompletedTask;public Task AddAlbumItemAsync(GalleryAlbumItem i,CancellationToken c=default)=>Task.CompletedTask;public Task RemoveAlbumItemAsync(string a,string m,CancellationToken c=default)=>Task.CompletedTask;public Task SetAlbumCoverAsync(string a,string? m,CancellationToken c=default)=>Task.CompletedTask;public Task<GalleryApplicationState?> GetApplicationStateAsync(CancellationToken c=default)=>Task.FromResult<GalleryApplicationState?>(null);public Task SaveApplicationStateAsync(GalleryApplicationState s,CancellationToken c=default)=>Task.CompletedTask;public Task<GalleryLaunchPreference?> GetLaunchPreferenceAsync(GalleryLaunchPreferenceScope s,string? id,CancellationToken c=default)=>Task.FromResult<GalleryLaunchPreference?>(null);public Task SaveLaunchPreferenceAsync(GalleryLaunchPreference p,CancellationToken c=default)=>Task.CompletedTask;public Task<GalleryBackgroundSelection?> GetBackgroundAsync(CancellationToken c=default)=>Task.FromResult<GalleryBackgroundSelection?>(null);public Task SaveBackgroundAsync(GalleryBackgroundSelection? s,CancellationToken c=default)=>Task.CompletedTask;
}
